mapper.select:
SELECT FROM visitor
ORDER BY visit_time DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE visitor
visitor_name = #{visitorName}, phone = #{phone}, visit_owner_id = #{visitOwnerId}, visit_owner = #{visitOwner}, house_no = #{houseNo}, visit_reason = #{visitReason}, car_plate = #{carPlate}, visit_time = #{visitTime}, leave_time = #{leaveTime}, status = #{status},
WHERE id = #{id}
